INSERT INTO `business_notice` VALUES ('1020260419492013073', '2020260419813713074', '2026年4月19日 12:00—16:00 系统维护通知', '1000', '<p>&nbsp;尊敬的各位业主/住户：&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp;为提升物业服务系统稳定性，优化使用体验，我司将于以下时间对物业系统进行例行维护，维护期间相关线上功能将暂时无法使用。&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp;维护时间：2026年4月19日 12:00—16:00</p><p>&nbsp; &nbsp; &nbsp; &nbsp;影响范围：小区门禁、线上缴费、报修报事、业主查询等系统功能。&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp;维护期间如有紧急事宜，可前往物业服务中心或联系物业工作人员处理。由此给您带来的不便，敬请谅解。\n\n感谢您的理解与配合！</p><p data-we-empty-p=\"\" style=\"text-align:right;\">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 物业服务中心\n2026年4月19日<br/></p>', '2026041312720002', '302025040775460040', '2026-04-19 12:01:04', '2026-04-19 12:01:04', 'ADD', '2050-01-01 00:00:00', '005', '2026041312720002', '1000');
