INSERT INTO `business_notice` VALUES ('102026071502414444', '202026071515794445', '暴风雨预警、防范', '1001', '<p>各位员工：根据天气预报显示，近期广西将有暴风雨，各项目管理人员、员工做好安全防范、防洪工作，请各位工作人员做好以下安全防备工作：</p><p>1、检查地下室潜水泵是否正常运行，发现损坏、不能正常使用及时上报，确保大雨来临时潜水泵能正常运行。<br/>2、检查排水管、雨水井、排水口是否畅通。发现堵塞、满溢及时清理。<br/>3、检查公共设备设施、线路是否正常运行。<br/>4、准备好防洪沙袋，暴雨来临前做好布防工作，重点区域重点布防。<br/>5、重点检查低洼、易积水区域，排查消除安全隐患。<br/>6、电梯口做好防洪准备，防止雨水倒灌造成电梯损坏。<br/>7、各科室保洁关好门窗、水电开关等。<br/>8、注意楼栋外立面、楼顶、阳台是否有易坠物，及时排查消除安全隐患。<br/>9、雨天路滑，同事们上下班路上注意行车安全，避开易内涝积水、危险路段。<br/>同事们辛苦啦[握手]<br/>南宁凯宜物业<br/>       2026年7月15日</p>', '2026071539364277', '302026071541274140', '2026-07-15 02:53:51', '2026-07-15 10:53:52', 'ADD', '2050-01-01 00:00:00', '005', '2026071539364277', '1000');
